use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let cents = input.as_i64().unwrap_or(0);
    let pounds = cents as f64 / 100000000.0;
    let rounded_pounds = round(pounds);
    rounded_pounds.to_string()
}

fn round(num: f64) -> f64 {
    if num.fract() == 0.5 {
        num.ceil() - 0.5
    } else {
        num.round()
    }
}

fn main() {
    let input = serde_json::Value::from("{\"input\":-1230,\"expected\":\"-12.30\"}");
    let result = solve(input);
    println!("{}", result);
}
